def sync():
    registry=json.loads((HERE/'requirements.json').read_text(encoding='utf-8'))['records']
    records=[]
    for id,title,deps,module,output,a,b,verify,files,blockers in TASKS:
        related=[r for r in registry if r['task']==id]
        records.append({'id':id,'title':title,'dependencies':deps,'module':module,'owner_role':module,
          'output':output,'source_ids':[r['source_id'] for r in related],
          'acceptance':[a,b],'verification':verify,'proposed_files':files,'open_decisions':blockers,
          'status':'DRAFT_NOT_AUTHORIZED','readiness':'needs_baseline_review'+(' and decision_resolution' if blockers else '')})
    data={'version':'0.1','status':'proposal_not_active_tracker','active_tracker':'tasks/todo.md','tasks':records}
    (HERE/'backlog.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    lines=['# Backlog toàn sản phẩm — task chi tiết để rà\n\nKhông thay tasks/todo.md đang dở của mẫu E02a. Toàn bộ task dưới đây DRAFT_NOT_AUTHORIZED; file paths là dự kiến chưa tồn tại. Mỗi task có tối đa3 file boundary đề xuất; nếu khi Plan thực tế vượt5file hoặc một phiên tập trung thì phải tách tiếp trước Ready. Không cam kết thời lượng/ngày phát hành.\n',
      '## Milestones và task graph\n\nP00 ràbaseline/contracts/licenses; P01 khép mẫu; P02 Unity/Windowsprobe; P03 localAIbenchmark; P10 nguồn/quyền; P20 avatar; P30 life; P40 trải nghiệm/tác vụ; P50 dữ liệu/phân phối; P60 integration/release. Không tạo task parser/file-reader bị hoãn.\n']
    for t in records:
        lines.append(f"## {t['id']} — {t['title']}\n\n- Status: {t['status']}; owner: `{t['owner_role']}`.\n- Đầu ra: {t['output']}.\n- Requirements: {', '.join(t['source_ids']) or 'Enabler cho SP09 và các task phụ thuộc; không phải tính năng mới.'}\n- Phụ thuộc: {', '.join(t['dependencies']) or 'Không task trước; vẫn phải được rà phạm vi.'}\n- Blocker: {', '.join(t['open_decisions']) or 'Baseline/thiết kế của lát cần rà; không mặc định Ready.'}\n- [ ] {t['acceptance'][0]}\n- [ ] {t['acceptance'][1]}\n- Kiểm chứng: {t['verification']}\n- File boundary dự kiến: "+'; '.join(f'`{p}`' for p in t['proposed_files'])+'\n')
    lines.append('## Checkpoints\n\nC-BASE: baseline/contracts/qualityreview trước productioncode. C-PROBE: E02a/E-INT/E04 có bằng chứng hoặc userchấp nhận giới hạn rõ trước reuse. C-SLICE: P60-01 chứng minh luồng kết hợp, không demoriêng. C-REGRESSION: SRS/AT/RTM actualevidence cả2mode. C-RELEASE: useracceptance/8h/privacy/data/license/cost/publicartifactreview; không auto publish.\n')
    (HERE/'BACKLOG.md').write_text('\n'.join(lines),encoding='utf-8')
    notes=json.loads((HERE/'human_task_notes.json').read_text(encoding='utf-8'))
    if set(notes) != {t['id'] for t in records}: raise ValueError('Human task notes differ from backlog')
    human=['# Từng công việc dành cho người đọc\n\nĐây là 52 việc dự kiến của toàn sản phẩm, chưa phải 52 việc đã được cho bắt đầu. Tên mã giúp nối với bản kỹ thuật; bạn không cần đọc tên file hoặc chọn thư viện. Những việc còn phụ thuộc phép thử/ý kiến phải giải quyết trước. Mẫu E02a đang làm vẫn được theo dõi riêng.\n']
    for t in records:
        human.append(f"## {t['id']} — {t['title']}\n\n{notes[t['id']]}\n\n**Làm sau:** {', '.join(t['dependencies']) or 'Rà yêu cầu hiện tại trước.'}\n")
    (HERE.parent/'HUMAN/07-CONG-VIEC.md').write_text('\n'.join(human),encoding='utf-8')
    print(f'Generated {len(records)} proposed tasks; active E02a tracker unchanged.')

